export function unpack(packed = PACKED) {
  const out = [];
  let previous = '';
  for (const token of packed.split(' ')) {
    const shared = token.charCodeAt(0) - 48;
    const word = previous.slice(0, shared) + token.slice(1);
    out.push(word);
    previous = word;
  }
  return out;
}


export const SCRABBLE_WORDS = unpack();








export const WORD_SET = new Set(SCRABBLE_WORDS);


export const isWord = (word) => WORD_SET.has(String(word ?? '').toUpperCase());


export const WORD_COUNT = SCRABBLE_WORDS.length;














export const COMMON_BITS = '';

let common = null;





export function commonWords() {
  if (common) return common;
  const bytes = atob(COMMON_BITS);
  common = SCRABBLE_WORDS.filter((_, i) => (bytes.charCodeAt(i >> 3) >> (i & 7)) & 1);
  return common;
}


export const COMMON_COUNT = 40577;
